








    -- Generated by AutomateDV (formerly known as dbtvault)

    

WITH row_rank_1 AS (
    SELECT DISTINCT ON (rr.CUSTOMER_PK) rr.CUSTOMER_PK, rr.CUSTOMER_KEY, rr.LOAD_DATE, rr.RECORD_SOURCE
    FROM "postgres"."dbt"."stg_customers" AS rr
    WHERE rr.CUSTOMER_PK IS NOT NULL
    ORDER BY rr.CUSTOMER_PK, rr.LOAD_DATE
),

row_rank_2 AS (
    SELECT DISTINCT ON (rr.CUSTOMER_PK) rr.CUSTOMER_PK, rr.CUSTOMER_KEY, rr.LOAD_DATE, rr.RECORD_SOURCE
    FROM "postgres"."dbt"."stg_customers_crm" AS rr
    WHERE rr.CUSTOMER_PK IS NOT NULL
    ORDER BY rr.CUSTOMER_PK, rr.LOAD_DATE
),

stage_union AS (
    SELECT * FROM row_rank_1
    UNION ALL
    SELECT * FROM row_rank_2
),

row_rank_union AS (SELECT DISTINCT ON (ru.CUSTOMER_PK) ru.*
    FROM stage_union AS ru
    WHERE ru.CUSTOMER_PK IS NOT NULL
    ORDER BY ru.CUSTOMER_PK, ru.LOAD_DATE, ru.RECORD_SOURCE ASC
),

records_to_insert AS (
    SELECT a.CUSTOMER_PK, a.CUSTOMER_KEY, a.LOAD_DATE, a.RECORD_SOURCE
    FROM row_rank_union AS a
    LEFT JOIN "postgres"."dbt"."hub_customer" AS d
    ON a.CUSTOMER_PK = d.CUSTOMER_PK
    WHERE d.CUSTOMER_PK IS NULL
)

SELECT * FROM records_to_insert